"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["3850"],{26748(e,t,i){i.d(t,{Ay:()=>r,RM:()=>o});var n=i(74848),a=i(28453);let o=[{value:"I. The Striking Similarities in Chinese Dynastic Succession and the Major Opportunity Facing the Chinese Nation",id:"i-the-striking-similarities-in-chinese-dynastic-succession-and-the-major-opportunity-facing-the-chinese-nation",level:3},{value:"II. From Marx&#39;s Five-Stage Theory: The Current Historical Stage of the World",id:"ii-from-marxs-five-stage-theory-the-current-historical-stage-of-the-world",level:3},{value:"III. The Historic Resonance Between China&#39;s National Revival Cycle and the World Economic Cycle Has Produced a Historic Opportunity",id:"iii-the-historic-resonance-between-chinas-national-revival-cycle-and-the-world-economic-cycle-has-produced-a-historic-opportunity",level:3},{value:"IV. Geopolitical and Currency Strategy Under This Historic Opportunity",id:"iv-geopolitical-and-currency-strategy-under-this-historic-opportunity",level:3},{value:"Appendix: This ID&#39;s Old Post \u2014 Explaining the Mechanism of Exchange Rate Formation and America&#39;s Currency Strategy in the Simplest Possible Terms",id:"appendix-this-ids-old-post--explaining-the-mechanism-of-exchange-rate-formation-and-americas-currency-strategy-in-the-simplest-possible-terms",level:3},{value:"Replies",id:"replies",level:3}];function s(e){let t={blockquote:"blockquote",h1:"h1",h3:"h3",header:"header",li:"li",ol:"ol",p:"p",...(0,a.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.header,{children:(0,n.jsx)(t.h1,{id:"historic-resonance-between-the-national-revival-cycle-and-the-world-economic-cycle-national-geopolitical-and-currency-strategy",children:"Historic Resonance Between the National Revival Cycle and the World Economic Cycle: National Geopolitical and Currency Strategy"})}),"\n",(0,n.jsxs)(t.blockquote,{children:["\n",(0,n.jsx)(t.p,{children:"2006/9/23 21:26:40"}),"\n"]}),"\n",(0,n.jsxs)(t.blockquote,{children:["\n",(0,n.jsx)(t.p,{children:"Compiled from an old post originally written in 2003"}),"\n"]}),"\n",(0,n.jsx)(t.h3,{id:"i-the-striking-similarities-in-chinese-dynastic-succession-and-the-major-opportunity-facing-the-chinese-nation",children:"I. The Striking Similarities in Chinese Dynastic Succession and the Major Opportunity Facing the Chinese Nation"}),"\n",(0,n.jsx)(t.p,{children:'History always possesses a mysterious and striking similarity. For example, almost all the most critical events in China in the last century were related to the number 9. In the succession of Chinese dynasties, there is a particularly notable pattern: after a great period of chaos, a brief unifying dynasty (always lasting only two reigns) is immediately followed by a long and powerful dynasty. Before the true peak arrives, there is always a so-called "female calamity." For instance, after the Spring and Autumn / Warring States period came Qin (only two reigns), followed by Han, the Empress L\xfc, then the prosperity of Emperors Wen and Jing leading to the great zenith under Emperor Wu. After the Three Kingdoms, the two Jin dynasties, and the Northern and Southern Dynasties came Sui (only two reigns), followed by Tang, Empress Wu Zetian, then the great zenith under Emperor Xuanzong. From 1840 onward there was a great period of chaos, the Republic unified the country\u2014also two "reigns" (Sun and Chiang), then the People\'s Republic was established, Jiang Qing, and then a true period of national strength should emerge. Clearly, the Chinese nation is in the historical grand uptrend of surging toward the third peak since Emperor Wu of Han and the Kaiyuan era of Tang.'}),"\n",(0,n.jsx)(t.h3,{id:"ii-from-marxs-five-stage-theory-the-current-historical-stage-of-the-world",children:"II. From Marx's Five-Stage Theory: The Current Historical Stage of the World"}),"\n",(0,n.jsxs)(t.ol,{children:["\n",(0,n.jsx)(t.li,{children:"Marx's five-stage theory is built on a complete classification of real-world relations between people, and between people and nature."}),"\n"]}),"\n",(0,n.jsx)(t.p,{children:"This unified classification is based on the circumstances of real people in real society\u2014their relations with each other and with nature: 1. Society has no subordination of one group to another, but the whole of society must collectively depend on nature\u2014this is primitive society. 2. Under dependence on nature, one group of people is subordinate to another based on personal bondage\u2014this is slave society. 3. Under dependence on nature, subordination of one group to another no longer requires personal bondage but is instead mediated through external things such as land, titles, etc.\u2014this is feudal society. 4. Subordination of one group to another no longer exists in society; instead, all people without exception are subordinate to a non-natural external thing: capital\u2014this is capitalist society. 5. Remove that final subordination from stage 4, achieving complete reconciliation between real people and society, and between people and nature\u2014this is communist society."}),"\n",(0,n.jsxs)(t.ol,{start:"2",children:["\n",(0,n.jsx)(t.li,{children:"Leninist socialism is a strategically nationalist misreading; it is an anti-capitalist capitalist process."}),"\n"]}),"\n",(0,n.jsx)(t.p,{children:'Lenin probably\u2014whether intentionally or not\u2014misunderstood the phrase "abolish private property" in the Communist Manifesto, taking public vs. private ownership as the distinguishing criterion (here one can see the Hegelian character). But Marx analyzed this question from the standpoint of the two real relations\u2014between people, and between people and nature. The two approaches are fundamentally different. The public/private criterion is merely an inference under specific premises\u2014necessary but not sufficient. Socialism must be public ownership, but public ownership is not necessarily socialism. If an inference is turned into a premise\u2014or even the sole premise\u2014it becomes a limping maxim that ultimately obscures the truth.'}),"\n",(0,n.jsx)(t.p,{children:'Leninist socialism always jumped directly from feudal society, and all inevitably tended toward the Stalinist model. Simply replace "capital" in the definition "capitalist society is where subordination of one group to another no longer exists, and all people without exception are subordinate to a non-natural external thing: capital" with "power" or "power-capital," and you get the best definition of Stalinism. From this, the following seemingly incredible statement becomes clear: Stalinist socialism is merely a certain type of capitalism. And from this, an even more startling statement follows: the Leninist socialist revolutions that swept across the twentieth century were, in essence, merely a certain type of capitalist process. The rapid conversion of power or power-capital into capital after the Soviet-Eastern European upheavals demonstrates their common origin.'}),"\n",(0,n.jsx)(t.p,{children:"The historical significance of Leninist socialism lies in its being the best nationalist strategy available at the time. A backward feudal nation, under the conditions of that era, would face annihilation following the conventional path. Lenin's\u2014whether intentional or not\u2014strategy saved the largest majority of backward nations in the world at that time, giving them a chance to catch their breath and catch up. In essence, Leninist socialism is a nationalist process\u2014an anti-capitalist capitalist movement by backward nations to avoid being devoured by nations that entered capitalism first. In this respect, Lenin is immortal\u2014the teacher of all the weak nations of the world."}),"\n",(0,n.jsxs)(t.ol,{start:"3",children:["\n",(0,n.jsx)(t.li,{children:"The rebellion against the fate that Leninism necessarily leads to Stalinism constitutes the most basic logic of Mao Zedong's Cultural Revolution thinking."}),"\n"]}),"\n",(0,n.jsx)(t.p,{children:"The Cultural Revolution was Mao Zedong's great attempt to break free from the historical fate that the Leninist model inevitably leads to Stalinism; its failure carries a cruel historical inevitability. Lucidity is often painful\u2014Mao Zedong's Cultural Revolution rebellion was destined to fail within that lucidity. Resisting Stalinization was in fact also resisting a process of capitalization. But in the two real relations between people and between people and nature, the latter plays the decisive role. The former certainly has a reactive effect, but attempting to resist a certain real tendency in the people-nature relation by adjusting the people-people relation\u2014the impossibility of this constitutes the inevitability of failure for all Cultural Revolution-type movements. Any contingent factors are irrelevant before this inevitability. In this respect, Mao Zedong was undoubtedly tragic\u2014but it was the tragedy of a hero."}),"\n",(0,n.jsx)(t.p,{children:"From feudal to capitalist society, the key change is that subordination of one group to another no longer exists. The old dependency relations are broken. All people without exception become subordinate to a non-natural external thing: X. However many realistic possibilities there are for X, that's how many types of capitalism exist. From the 17th century to the present, all changes and struggles have merely been the process by which different types of capitalism emerge, grow strong, and compete through struggle for ultimate dominance. All ideological disputes at the level of real nation-states are, fundamentally, conducted within the capitalist premise. The essential meaning of the Cold War in the second half of the twentieth century then becomes clear: it was the struggle between Anglo-American capitalism and Stalinist capitalism for ultimate dominance. Mao Zedong saw through all of this and proposed the Three Worlds theory\u2014but fundamentally, this was a nationalist strategy, unrelated to socialism."}),"\n",(0,n.jsxs)(t.ol,{start:"4",children:["\n",(0,n.jsx)(t.li,{children:"The inevitability of the Cultural Revolution's failure means that facing capitalist globalization has become an inescapable reality."}),"\n"]}),"\n",(0,n.jsx)(t.p,{children:'Socialism in Marx\'s sense\u2014as the initial stage of communism\u2014cannot be achieved in a single country alone. It can only be a global event following the globalization of capital. Lenin\'s strategy was a nationalist strategy, and Deng Xiaoping\'s "socialism with Chinese characteristics" and "primary stage of socialism" strategy should likewise be understood as a nationalist strategy.'}),"\n",(0,n.jsx)(t.p,{children:"Capitalist globalization is an inescapable reality that must be faced\u2014it is the inevitable trend of capitalism's internal developmental logic. How to make one's own voice heard within this grand trend, or even guide this process, is the most important, core question."}),"\n",(0,n.jsx)(t.h3,{id:"iii-the-historic-resonance-between-chinas-national-revival-cycle-and-the-world-economic-cycle-has-produced-a-historic-opportunity",children:"III. The Historic Resonance Between China's National Revival Cycle and the World Economic Cycle Has Produced a Historic Opportunity"}),"\n",(0,n.jsx)(t.p,{children:"In the economic cycles of capitalism, the overall saturation level has a relationship with population that exhibits a structure of 5x quantum-like increments\u2014resembling electron orbital quantization. Populations of 10 million and 50 million were the two basic population thresholds for achieving so-called great-power status in the medieval and early modern periods. After Great Britain completed its hegemony at the 50-million level, the United States and the Soviet Union completed their historical performances at the 250-million level. The next level is 1.25 billion. Current alliances among world economic entities are preparations for capital-globalization competition at the 1.25-billion level."}),"\n",(0,n.jsx)(t.p,{children:"In 1929, the old 50-million-level dominant cycle of Britain and Germany ended, and the 250-million-level dominant cycle of the US and USSR began. This 90-year cycle formed the mid-cycle oil crisis correction at its halfway point in 1974. The same-level competition between these two different types of capitalism\u2014the US and USSR\u2014ended with America's victory. However, the peak of this cycle already appeared in 2000. The enormous correction ahead will reach 1929-level severity by 2019, thereby declaring the end of this level and the beginning of the 1.25-billion-level world economic cycle. (To keep this article from getting too long, the detailed economic analysis is omitted here; only the conclusions are given.)"}),"\n",(0,n.jsx)(t.p,{children:"After 1949, China's explosive population growth was one of Mao Zedong's greatest historical contributions. China thereby automatically entered the competition as a powerful contender for the 1.25-billion-level world economic cycle. The synthesis of China's national revival cycle with the world economic cycle has produced a historic opportunity. How to seize it is the most important question before us."}),"\n",(0,n.jsx)(t.h3,{id:"iv-geopolitical-and-currency-strategy-under-this-historic-opportunity",children:"IV. Geopolitical and Currency Strategy Under This Historic Opportunity"}),"\n",(0,n.jsx)(t.p,{children:'The current strategy\u2014centered on the Yangtze River basin, with North and South China as two flanks\u2014is coordinated with the so-called "hiding capabilities and biding time" approach and conciliatory diplomacy. It cannot achieve anything great and harbors enormous hidden dangers. From a long-term perspective, the strategic triangle should be constructed from the Bohai Rim region, the Pearl River Delta region, and the Qinchuan (Wei River Plain) region. Starting from the Pearl River Delta to connect Southeast Asia; starting from the Qinchuan region along the ancient Silk Road to connect Central and West Asia\u2014together forming a two-pronged pincer around India. Starting from the Bohai Rim to connect Northeast Asia\u2014suppressing Japanese and Russian influence in the region. Using this grand triangle as its foundation, China will gradually become the king of Asia. Its territory (or vassal-like sphere of influence) should extend from the Ural Mountains eastward to the sea facing the Americas, from the Arctic Ocean down to the Pacific looking over Australia\u2014forming the world\'s axis, with Europe and the Americas as its two wings.'}),"\n",(0,n.jsx)(t.p,{children:"But against the backdrop of capitalist globalization, a nation's currency strategy is even more important. All modern wars are fundamentally currency wars\u2014determined by the high degree of capitalization in modern society. For a highly capitalized society, any activity detached from capital is fundamentally meaningless, and war is no exception."}),"\n",(0,n.jsx)(t.p,{children:'From the perspective of the 1.25-billion-level world economic cycle, the most competitive currencies will be the US dollar, the euro, the rupee, and the renminbi. For the renminbi to ultimately prevail in this currency war\u2014like the drafting technique in distance running\u2014China must at the current stage insist on a "non-pegged peg" policy toward the US dollar, firmly and persistently maintaining renminbi-dollar exchange rate stability. On this foundation, China should gradually expand its influence over the Asian region, subtly supplanting the yen\'s position and progressively becoming the de facto Asian currency. Then, leveraging the enormous differential built up during the first phase and in coordination with the world economic cycle, China should choose the right moment to release it\u2014destroying the US dollar in a single carefully orchestrated strike. Finally, in a long, grueling, back-and-forth process, China should leverage the new 1.25-billion-level world economic cycle to establish its lead over the United States, becoming the true frontrunner of the 1.25-billion-level world economic cycle and completing the great national revival.'}),"\n",(0,n.jsx)(t.h3,{id:"appendix-this-ids-old-post--explaining-the-mechanism-of-exchange-rate-formation-and-americas-currency-strategy-in-the-simplest-possible-terms",children:"Appendix: This ID's Old Post \u2014 Explaining the Mechanism of Exchange Rate Formation and America's Currency Strategy in the Simplest Possible Terms"}),"\n",(0,n.jsx)(t.p,{children:"Some bookworms, the moment exchange rates are mentioned, start reciting a pile of definitions\u2014but that's useless. It's like talking about P/E ratios in the stock market\u2014all boring tricks. Exchange rates, put plainly, are a game among great powers, no different from a market maker manipulating stocks. Some might say: with such enormous daily currency trading volumes, how can it be manipulated? If you think market manipulation always requires money to pump prices, that's the crudest method. Manipulation ultimately means manipulating human psychology\u2014wherever there are people, there can be manipulation. If you don't understand this in financial markets, losing money is only to be expected."}),"\n",(0,n.jsx)(t.p,{children:"The US is a master of exchange rate manipulation, but exchange rate manipulation ultimately serves its overall interests. The biggest crisis facing the US economy is bubble-ization, and America's current below-zero savings rate has pushed its economic danger to unprecedented levels. In a sense, America the stock has been pumped to dizzyingly cold heights. Like a manipulated stock, the key now is preventing large-scale capital flight\u2014otherwise there'll be consecutive crashes. Because the decline from 2000 was extremely rapid, most hot money couldn't exit effectively, so large-scale capital flight hasn't yet occurred. The current large-scale rebound is creating the opportunity for capital flight. Once the rebound peaks, the anticipated large-scale capital flight will truly begin."}),"\n",(0,n.jsx)(t.p,{children:"To prevent the above scenario, America's only viable currency strategy is to devalue the currency to a corresponding low level before this major rebound completes. This prevents dollar-denominated capital from cashing out and fleeing at a high exchange rate. In effect, it's putting a collar on dollar capital at the currency level, so that the resolve and magnitude of cashed-out dollar capital flight will be greatly reduced. This is America's only non-war viable method to prevent the crash of America-the-stock."}),"\n",(0,n.jsx)(t.p,{children:"But this strategy has one achilles heel: if there's a currency with enormous capacity that tightly tracks the dollar, then all the dollar's devaluation calculations fall apart\u2014and the renminbi is precisely that currency. The renminbi's peg to the dollar gives dollar assets a smooth escape channel after being cashed out. The renminbi economy's greatest advantage over the dollar economy is extremely low bubble-ization and an extremely high savings rate\u2014this is a mortal threat to the American economy. As long as the renminbi strategy is maintained and the pool is dug sufficiently deep, the dollar's devaluation strategy will be completely thwarted. Once that strategy is thwarted, the American economy will face the most enormous shock. This is also the practical basis for the prediction in previous posts of the 90-year-cycle world economic crisis in 2019\u2014the correct renminbi strategy will accelerate and deepen this process."}),"\n",(0,n.jsx)(t.h3,{id:"replies",children:"Replies"}),"\n",(0,n.jsx)("div",{class:"blog-comment",children:(0,n.jsxs)(t.p,{children:[(0,n.jsx)("span",{class:"blog-comment-chan",children:"\u7F20\u4E2D\u8BF4\u7985"})," 2006/9/23 21:49:21",(0,n.jsx)("br",{}),"\nReplies unrelated to this post are declined. Replies about Kong Qingdong and such, please post in the relevant thread."]})})]})}function r(e={}){let{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(s,{...e})}):s(e)}},65013(e,t,i){i.r(t),i.d(t,{metadata:()=>n,default:()=>p,frontMatter:()=>r,contentTitle:()=>l,toc:()=>h,assets:()=>c});var n=JSON.parse('{"id":"stocks/nationalstrategy","title":"","description":"","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/stocks/nationalstrategy.md","sourceDirName":"stocks","slug":"/stocks/nationalstrategy","permalink":"/en/stocks/nationalstrategy","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"nationalstrategy","title":"","hide_table_of_contents":false,"sidebar_label":"National Geopolitical and Monetary Strategy Under the Historic Resonance of National Revival Cycles and World Economic Cycles (2006/9/23 21:26:40)"},"sidebar":"stocksExtendedSidebar","previous":{"title":"The Supreme Survival Principle of Capitalist Society! (2006/9/14 11:37:47)","permalink":"/en/stocks/supremelaw"},"next":{"title":"That Night, His Body Fluids Splashed All Over Me (14) (2006/10/8 23:51:21)","permalink":"/en/stocks/fluid14"}}'),a=i(74848),o=i(28453),s=i(26748);let r={id:"nationalstrategy",title:"",hide_table_of_contents:!1,sidebar_label:"National Geopolitical and Monetary Strategy Under the Historic Resonance of National Revival Cycles and World Economic Cycles (2006/9/23 21:26:40)"},l,c={},h=[...s.RM];function d(e){return(0,a.jsx)(s.Ay,{})}function p(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(d,{...e})}):d(e)}},28453(e,t,i){i.d(t,{R:()=>s,x:()=>r});var n=i(96540);let a={},o=n.createContext(a);function s(e){let t=n.useContext(o);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:s(e.components),n.createElement(o.Provider,{value:t},e.children)}}}]);